<section class="lm-section lm-section-soft"><div class="lm-container"><div class="lm-panel">
  <div class="lm-panel-body d-flex justify-content-between align-items-center flex-wrap gap-2"><h2 class="lm-panel-title mb-0">All users</h2><span class="lm-status"><?= count($users) ?> users</span></div>
